<script lang="ts">
 import {onMount} from 'svelte';import type {ContextPlan} from '../lib/ai-context';import {sourceReason} from '../lib/chat-input';
 let {plan,currentPdf,busy,excluded,changeCurrent,toggle,close}:{plan:ContextPlan|null;currentPdf:boolean;busy:boolean;excluded:string[];changeCurrent:(value:boolean)=>void;toggle:(id:string)=>void;close:()=>void}=$props();let dialog:HTMLDialogElement;onMount(()=>dialog.showModal());
</script>
<dialog class="context-choices" bind:this={dialog} aria-label="本轮上下文选项" oncancel={close}><header><strong>本轮上下文选项</strong><button aria-label="关闭上下文选项" title="关闭" onclick={close}>×</button></header><label><input type="checkbox" checked={currentPdf} disabled={busy} onchange={e=>changeCurrent(e.currentTarget.checked)}/>从当前整份 PDF 检索相关页</label><p>只发送实际选定和检索到的内容。历史提供必要文字，旧截图不自动重发。你选定和标注的来源优先，自动检索只填充剩余容量。</p>{#if busy}<p role="status">正在准备来源…</p>{:else if plan}{#if plan.trimmed}<p class="trimmed" role="status">本轮容量已满，自动检索减少了 {plan.trimmed} 个次要来源；你选定和标注的来源都完整保留。</p>{/if}{#each plan.sources as source}<div class="source-row"><span>{source.name} · {source.page}页<small>{sourceReason(source.reasons)}{source.image?' · 图像':''}</small></span><button title={excluded.includes(source.id)?'恢复来源':'移除此轮来源'} aria-label={(excluded.includes(source.id)?'恢复':'移除')+'来源 '+source.id} onclick={()=>toggle(source.id)}>{excluded.includes(source.id)?'恢复':'移除'}</button></div>{/each}{:else}<p>输入问题后可检查实际检索来源；也可直接发送。</p>{/if}</dialog>
<style>.context-choices{width:min(420px,90vw);max-height:70vh;border:1px solid #cbd6df;border-radius:6px;padding:12px;color:#41566a;font-size:12px;}.context-choices::backdrop{background:#20314235;}header,.source-row{display:flex;align-items:center;justify-content:space-between;gap:8px;}header{margin-bottom:12px;}.source-row{padding:7px 0;border-top:1px solid #e7edf2;}.source-row span{min-width:0;overflow-wrap:anywhere;}small{display:block;font-size:10px;color:#758898;}p{color:#778896;font-size:11px;line-height:1.6;}label{display:flex;align-items:center;gap:4px;}button{border:1px solid #d5dce3;border-radius:4px;padding:3px 6px;color:#41566a;background:white;font-size:11px;white-space:nowrap;}button:hover{background:#edf2f7;}.trimmed{background:#f4f7fa;border:1px solid #dbe4ec;border-radius:4px;padding:6px 8px;color:#5c6f81;}</style>
